async function searchProducts(n,t){t.innerHTML='<div class="text-center py-5 w-100">  <div class="spinner-border text-primary" role="status"><\/div><\/div>';try{const u="/Catalog/Search?query="+encodeURIComponent(n),i=await fetch(u,{headers:{Accept:"text/html"}});if(!i.ok)throw new Error("HTTP "+i.status);const r=await i.text();t.innerHTML=r.trim()?r:'<div class="alert alert-info w-100">Ничего не найдено<\/div>'}catch(i){t.innerHTML='<div class="alert alert-danger w-100">Ошибка поиска<\/div>';console.error(i)}}document.addEventListener("DOMContentLoaded",function(){const n=document.getElementById("searchInput"),t=document.getElementById("catalogGrid");if(n&&t){let i;n.addEventListener("input",function(){clearTimeout(i);const r=n.value.trim();if(r.length===0){window.location.reload();return}i=setTimeout(function(){searchProducts(r,t)},300)})}});